93					return insn.getArg(0);
94				case CONST_STR:
95					return ((ConstStringNode) insn).getString();
96				case CONST_CLASS:
97					return ((ConstClassNode) insn).getClsType();
98				case SGET:
99					FieldInfo f = (FieldInfo) ((IndexInsnNode) insn).getIndex();
100					FieldNode fieldNode = root.resolveField(f);
101					if (fieldNode == null) {
102						LOG.warn("Field {} not found", f);
