162				InsnArg arg = insn.getArg(i);
163				if (arg.isInsnWrap()) {
164					InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
165					replaceInsnsInInsn(mth, wrapInsn, replaceFunction);
166					InsnNode replace = replaceFunction.apply(wrapInsn);
167					if (replace != null) {
168						InsnRemover.unbindArgUsage(mth, arg);
169						insn.setArg(i, InsnArg.wrapInsnIntoArg(replace));
170					}
171				}
172			}
173		}
