285		public static boolean containsVar(InsnArg insnArg, RegisterArg arg) {
286			if (insnArg.isRegister()) {
287				return ((RegisterArg) insnArg).sameRegAndSVar(arg);
288			}
289			if (insnArg.isInsnWrap()) {
290				InsnNode wrapInsn = ((InsnWrapArg) insnArg).getWrapInsn();
291				return containsVar(wrapInsn, arg);
292			}
293			return false;
294		}
