1	package jadx.core.utils;
2	
3	import java.text.SimpleDateFormat;
4	import java.util.ArrayList;
5	import java.util.Collections;
6	import java.util.Date;
7	import java.util.List;
8	import java.util.function.IntConsumer;
9	
10	import org.jetbrains.annotations.Nullable;
11	
12	import jadx.api.JadxArgs;
13	import jadx.api.args.IntegerFormat;
14	import jadx.core.deobf.NameMapper;
15	import jadx.core.utils.exceptions.JadxRuntimeException;
16	
17	public class StringUtils {
18		private static final StringUtils DEFAULT_INSTANCE = new StringUtils(new JadxArgs());
19		private static final String WHITES = " \t\r\n\f\b";
20		private static final String WORD_SEPARATORS = WHITES + "(\")<,>{}=+-*/|[]\\:;'.`~!#^&";
21	
22		public static StringUtils getInstance() {
23			return DEFAULT_INSTANCE;
24		}
25	
26		private final boolean escapeUnicode;
27		private final IntegerFormat integerFormat;
28	
29		public StringUtils(JadxArgs args) {
30			this.escapeUnicode = args.isEscapeUnicode();
31			this.integerFormat = args.getIntegerFormat();
32		}
33	
34		public IntegerFormat getIntegerFormat() {
35			return integerFormat;
36		}
37	
38		public static void visitCodePoints(String str, IntConsumer visitor) {
39			int len = str.length();
40			int offset = 0;
41			while (offset < len) {
42				int codePoint = str.codePointAt(offset);
43				visitor.accept(codePoint);
44				offset += Character.charCount(codePoint);
45			}
46		}
47	
48		public String unescapeString(String str) {
49			int len = str.length();
50			if (len == 0) {
51				return "\"\"";
52			}
53			StringBuilder res = new StringBuilder();
54			res.append('"');
55			visitCodePoints(str, codePoint -> processCodePoint(codePoint, res));
56			res.append('"');
57			return res.toString();
58		}
59	
60		private void processCodePoint(int codePoint, StringBuilder res) {
61			String str = getSpecialStringForCodePoint(codePoint);
62			if (str != null) {
63				res.append(str);
64				return;
65			}
66			if (isEscapeNeededForCodePoint(codePoint)) {
67				res.append("\\u").append(String.format("%04x", codePoint));
68			} else {
69				res.appendCodePoint(codePoint);
70			}
71		}
72	
73		private boolean isEscapeNeededForCodePoint(int codePoint) {
74			if (codePoint < 32) {
75				return true;
76			}
77			if (codePoint < 127) {
78				return false;
79			}
80			if (escapeUnicode) {
81				return true;
82			}
83			return !NameMapper.isPrintableCodePoint(codePoint);
84		}
85	
86		/**
87		 * Represent single char the best way possible
88		 */
