	}

	public String formatLong(long l, boolean cast) {
		if (integerFormat == IntegerFormat.AUTO) {
			if (l == Long.MAX_VALUE) {
				return "Long.MAX_VALUE";
			}
			if (l == Long.MIN_VALUE) {
